const char *tokenText1(uint8_t token) { return kSingle[token]; }

const char *tokenText2(uint16_t token) {
  int lo = 0, hi = (int)(sizeof(kDouble) / sizeof(kDouble[0])) - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (kDouble[mid].code == token) return kDouble[mid].text;
    if (kDouble[mid].code < token) lo = mid + 1;
    else hi = mid - 1;
  }
  return nullptr;
}

